('poi_malaga_mirador_gibralfaro', 'poi', 'uk', 'short_tip', 'Піднімайтеся автобусом №35 або пішки за 30 хв від центру — вид того вартий'),

('poi_malaga_muelle_uno', 'poi', 'ar', 'name', 'مويلي أونو وبالميرال دي لاس سورپريساس'),
