('poi_malaga_santo_cristo', 'poi', 'ar', 'name', 'كنيسة سانتو كريستو دي لا سالود'),
('poi_malaga_santo_cristo', 'poi', 'ar', 'description', 'كنيسة باروكية من القرن السابع عشر بواجهة رخامية حمراء لافتة، مرتبطة ارتباطًا وثيقًا بأسبوع الآلام في ملقة.'),
('poi_malaga_santo_cristo', 'poi', 'ar', 'short_tip', 'بجوار شارع لاريوس مباشرة، يسهل دمجها مع جولة وسط المدينة'),
